public static FMRentalsByCustController construct(Args _args)
{
    FMRentalsByCustController controller = new FMRentalsByCustController();
    controller.parmReportName(ssrsreportstr(FMRentalsByCustomer, Report));
    controller.parmArgs(_args);
    return controller;
}
